def _u(uid):
    return next(u for u in UNITS if u[0] == uid)


UNITS_ROWS = [[u[0], u[1], u[2], u[3], u[4], u[5], u[6], u[7], u[8], u[9], u[10], u[11], u[12], u[13], u[14], u[15],
               SKIP, u[16], u[17], SKIP, u[18]] for u in UNITS]
SCEN_ROWS = [s + [SKIP, SKIP, SKIP] for s in SCEN]
MATRIX_ROWS = []
_order = {}
for u in UNITS:
    sc = u[4]
    _order[sc] = _order.get(sc, 0) + 1
    typ = "Монетизационная" if u[15] in ("Прямое получение оплаты", "Подведение к оплате") and sc == "SC-007" else ("Основная" if _order[sc] == 1 else "Поддерживающая")
    oblig = "Обязательно для первой версии" if u[18] == "Оставить" else "Следующий выпуск"
    MATRIX_ROWS.append([f"M-{len(MATRIX_ROWS) + 1:03d}", sc, u[0], typ, oblig, _order[sc], "", "", u[3]])
NAV_ROWS = [[f"N-{i + 1:03d}", *n[:7], n[7], ""] for i, n in enumerate(NAV)]
STATE_ROWS = [[f"S-{i + 1:03d}", *s, SKIP] for i, s in enumerate(STATES)]
CONTENT_ROWS = [list(c) for c in CONTENT]
PASS_ROWS = []
for uid in PASSPORT_UNITS:
    u = _u(uid)
    nav = ", ".join(sorted({n[1] for n in NAV if n[0] == uid}))
    PASS_ROWS.append([uid, u[2], u[1], u[4], u[5], u[3], u[7], u[8], u[11], u[12], "→ " + nav if nav else "—",
                      PASSPORT_METRIC[uid], PASSPORT_RISK[uid], SKIP, SKIP])
PRIOR_ROWS = [[u[0], u[2], u[4], *u[20], SKIP, SKIP, u[3], u[18]] for u in UNITS]

